import{_ as e,o as i,c as o,a1 as a}from"./chunks/framework.DdbKPUhY.js";const _=JSON.parse('{"title":"Static File API Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/static-api.md","filePath":"spec/static-api.md"}'),s={name:"spec/static-api.md"};function r(n,t,c,l,d,h){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="static-file-api-spec" tabindex="-1">Static File API Spec <a class="header-anchor" href="#static-file-api-spec" aria-label="Permalink to &quot;Static File API Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Static File module serves static files from a root directory via HTTP. It provides configurable file serving with LRU cache integration, zero-copy sendfile (via libuv), MIME type detection, ETag/Last-Modified conditional requests, path traversal protection, and directory listing. The module is guarded by the <code>UVHTTP_FEATURE_STATIC_FILES</code> compile-time feature gate.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><h3 id="uvhttp-static-create" tabindex="-1">uvhttp_static_create <a class="header-anchor" href="#uvhttp-static-create" aria-label="Permalink to &quot;uvhttp_static_create&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_static_create(const uvhttp_static_config_t* config, uvhttp_static_context_t** context)</code></li><li><strong>Purpose</strong>: Create a static file serving context with an LRU cache</li><li><strong>Preconditions</strong>: <code>config</code> must be non-NULL with <code>root_directory</code> set to a valid path. <code>context</code> must be a non-NULL pointer to <code>uvhttp_static_context_t*</code>.</li><li><strong>Postconditions</strong>: On success, <code>*context</code> points to a valid context with an initialized LRU cache. On failure, <code>*context</code> is unchanged and no memory is allocated.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>config</code> or <code>context</code> is NULL</li><li><code>UVHTTP_ERROR_OUT_OF_MEMORY</code>: allocation failure</li><li><code>UVHTTP_ERROR_IO_ERROR</code>: cache creation failed</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li><li><strong>Feature gate</strong>: <code>#if UVHTTP_FEATURE_STATIC_FILES</code></li></ul><h3 id="uvhttp-static-free" tabindex="-1">uvhttp_static_free <a class="header-anchor" href="#uvhttp-static-free" aria-label="Permalink to &quot;uvhttp_static_free&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_static_free(uvhttp_static_context_t* ctx)</code></li><li><strong>Purpose</strong>: Free a static file context and all associated resources</li><li><strong>Preconditions</strong>: <code>ctx</code> can be NULL (no-op). Must have been created by <code>uvhttp_static_create</code>.</li><li><strong>Postconditions</strong>: The LRU cache is freed and the context memory is released. The pointer is invalid after return.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-static-handle-request" tabindex="-1">uvhttp_static_handle_request <a class="header-anchor" href="#uvhttp-static-handle-request" aria-label="Permalink to &quot;uvhttp_static_handle_request&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_result_t uvhttp_static_handle_request(uvhttp_static_context_t* ctx, void* request, void* response)</code></li><li><strong>Purpose</strong>: Handle an HTTP request by serving a static file</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid. <code>request</code> and <code>response</code> must be valid <code>uvhttp_request_t</code>/<code>uvhttp_response_t</code> pointers.</li><li><strong>Postconditions</strong>: On success, the file is served with appropriate headers. The response is sent via <code>uvhttp_response_send</code>. On failure, an appropriate HTTP status is set on the response.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: any argument is NULL</li><li><code>UVHTTP_ERROR_MALFORMED_REQUEST</code>: URL is NULL</li><li><code>UVHTTP_ERROR_HEADER_TOO_LARGE</code>: URL path exceeds buffer</li><li><code>UVHTTP_ERROR_NOT_FOUND</code>: file not found, returns 403 or 404</li><li><code>UVHTTP_ERROR_FILE_TOO_LARGE</code>: file exceeds <code>max_file_size</code>, returns 413</li><li><code>UVHTTP_ERROR_IO_ERROR</code>: file read failure, returns 500</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe. Must be called from the event loop thread.</li><li><strong>Send strategy</strong>: Files &lt; 4KB use direct read; files 4KB-10MB use chunked async sendfile; files &gt; 10MB use sendfile zero-copy; on sendfile failure, falls back to chunked transfer.</li></ul><h3 id="uvhttp-static-get-mime-type" tabindex="-1">uvhttp_static_get_mime_type <a class="header-anchor" href="#uvhttp-static-get-mime-type" aria-label="Permalink to &quot;uvhttp_static_get_mime_type&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_result_t uvhttp_static_get_mime_type(const char* file_path, char* mime_type, size_t buffer_size)</code></li><li><strong>Purpose</strong>: Get the MIME type for a file based on its extension</li><li><strong>Preconditions</strong>: <code>file_path</code> must be non-NULL. <code>mime_type</code> must be a non-NULL buffer of at least <code>buffer_size</code> bytes.</li><li><strong>Postconditions</strong>: <code>mime_type</code> is filled with the MIME type string. Returns <code>&quot;application/octet-stream&quot;</code> for unknown extensions.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>file_path</code> or <code>mime_type</code> is NULL, or <code>buffer_size</code> is 0</li></ul></li><li><strong>Thread safety</strong>: Thread-safe. Uses a static hash table for O(1) lookup.</li><li><strong>Performance</strong>: Hash table lookup for common extensions (html, css, js, png, jpg) with fallback linear scan for hash collisions.</li></ul><h3 id="uvhttp-static-is-safe-path" tabindex="-1">uvhttp_static_is_safe_path <a class="header-anchor" href="#uvhttp-static-is-safe-path" aria-label="Permalink to &quot;uvhttp_static_is_safe_path&quot;">​</a></h3><ul><li><strong>Signature</strong> (internal): The module provides <code>uvhttp_static_resolve_safe_path(const char* root_dir, const char* file_path, char* resolved_path, size_t buffer_size)</code></li><li><strong>Purpose</strong>: Resolve a file path and verify it is within the root directory (path traversal prevention)</li><li><strong>Preconditions</strong>: <code>root_dir</code>, <code>file_path</code>, and <code>resolved_path</code> must be non-NULL. <code>buffer_size</code> must be &gt; 0.</li><li><strong>Postconditions</strong>: On success, <code>resolved_path</code> contains the canonicalized absolute path. Returns 1 if safe, 0 otherwise.</li><li><strong>Error conditions</strong>: <ul><li>Returns 0 if any argument is NULL or buffer_size is 0</li><li>Returns 0 if the path fails URL validation (<code>uvhttp_validate_url_path</code>)</li><li>Returns 0 if the canonicalized path is not under the root directory</li><li>Returns 0 if the path does not exist (realpath fails)</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-static-generate-etag" tabindex="-1">uvhttp_static_generate_etag <a class="header-anchor" href="#uvhttp-static-generate-etag" aria-label="Permalink to &quot;uvhttp_static_generate_etag&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_result_t uvhttp_static_generate_etag(const char* file_path, time_t last_modified, size_t file_size, char* etag, size_t buffer_size)</code></li><li><strong>Purpose</strong>: Generate an ETag value for a file using <code>&quot;&lt;file_size&gt;-&lt;last_modified&gt;&quot;</code> format</li><li><strong>Preconditions</strong>: <code>file_path</code> and <code>etag</code> must be non-NULL. <code>buffer_size</code> must be &gt; 0.</li><li><strong>Postconditions</strong>: <code>etag</code> is filled with a quoted string in the format <code>&quot;&lt;size&gt;-&lt;mtime&gt;&quot;</code>.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>file_path</code> or <code>etag</code> is NULL, or <code>buffer_size</code> is 0</li></ul></li><li><strong>Thread safety</strong>: Thread-safe.</li></ul><h3 id="uvhttp-static-prewarm-cache" tabindex="-1">uvhttp_static_prewarm_cache <a class="header-anchor" href="#uvhttp-static-prewarm-cache" aria-label="Permalink to &quot;uvhttp_static_prewarm_cache&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_result_t uvhttp_static_prewarm_cache(uvhttp_static_context_t* ctx, const char* file_path)</code></li><li><strong>Purpose</strong>: Preload a specific file into the LRU cache (relative to root directory)</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid with a cache. <code>file_path</code> must be non-NULL and relative to the root directory.</li><li><strong>Postconditions</strong>: The file is read from disk and stored in the LRU cache with MIME type, ETag, and last-modified time.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>ctx</code> or <code>file_path</code> is NULL, or path is too long</li><li><code>UVHTTP_ERROR_NOT_FOUND</code>: file does not exist or is a directory</li><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: file exceeds <code>max_file_size</code></li><li><code>UVHTTP_ERROR_SERVER_INIT</code>: file read failure</li><li>Cache put failure is logged but does not return an error</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-static-prewarm-directory" tabindex="-1">uvhttp_static_prewarm_directory <a class="header-anchor" href="#uvhttp-static-prewarm-directory" aria-label="Permalink to &quot;uvhttp_static_prewarm_directory&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>int uvhttp_static_prewarm_directory(uvhttp_static_context_t* ctx, const char* dir_path, int max_files)</code></li><li><strong>Purpose</strong>: Preload all files in a directory into the LRU cache</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid with a cache. <code>dir_path</code> must be non-NULL and relative to the root directory. If <code>max_files</code> &gt; 0, at most <code>max_files</code> files are prewarmed.</li><li><strong>Postconditions</strong>: Returns the number of successfully prewarmed files. Returns -1 on failure.</li><li><strong>Error conditions</strong>: <ul><li>Returns -1: <code>ctx</code> or <code>dir_path</code> is NULL, cache is not initialized, directory path is too long, or directory does not exist</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-static-clear-cache" tabindex="-1">uvhttp_static_clear_cache <a class="header-anchor" href="#uvhttp-static-clear-cache" aria-label="Permalink to &quot;uvhttp_static_clear_cache&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_static_clear_cache(uvhttp_static_context_t* ctx)</code></li><li><strong>Purpose</strong>: Clear all entries from the LRU cache</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid.</li><li><strong>Postconditions</strong>: All cache entries are freed. Cache hit/miss statistics are preserved.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-static-get-cache-stats" tabindex="-1">uvhttp_static_get_cache_stats <a class="header-anchor" href="#uvhttp-static-get-cache-stats" aria-label="Permalink to &quot;uvhttp_static_get_cache_stats&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_static_get_cache_stats(uvhttp_static_context_t* ctx, size_t* total_memory_usage, int* entry_count, int* hit_count, int* miss_count, int* eviction_count)</code></li><li><strong>Purpose</strong>: Get cache statistics</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid. Output pointers can be NULL.</li><li><strong>Postconditions</strong>: Output parameters are filled with current cache statistics. If <code>ctx</code> or cache is NULL, all outputs are set to 0.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-static-get-cache-hit-rate" tabindex="-1">uvhttp_static_get_cache_hit_rate <a class="header-anchor" href="#uvhttp-static-get-cache-hit-rate" aria-label="Permalink to &quot;uvhttp_static_get_cache_hit_rate&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>double uvhttp_static_get_cache_hit_rate(uvhttp_static_context_t* ctx)</code></li><li><strong>Purpose</strong>: Get the cache hit rate as a percentage (0.0-100.0)</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid.</li><li><strong>Postconditions</strong>: Returns 0.0 if the cache is NULL or no requests have been made.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-static-cleanup-expired-cache" tabindex="-1">uvhttp_static_cleanup_expired_cache <a class="header-anchor" href="#uvhttp-static-cleanup-expired-cache" aria-label="Permalink to &quot;uvhttp_static_cleanup_expired_cache&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>int uvhttp_static_cleanup_expired_cache(uvhttp_static_context_t* ctx)</code></li><li><strong>Purpose</strong>: Remove all expired cache entries</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid.</li><li><strong>Postconditions</strong>: Returns the number of entries removed. Returns 0 if cache is NULL.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-static-set-sendfile-config" tabindex="-1">uvhttp_static_set_sendfile_config <a class="header-anchor" href="#uvhttp-static-set-sendfile-config" aria-label="Permalink to &quot;uvhttp_static_set_sendfile_config&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_static_set_sendfile_config(uvhttp_static_context_t* ctx, int timeout_ms, int max_retry, size_t chunk_size)</code></li><li><strong>Purpose</strong>: Configure sendfile parameters (timeout, retry, chunk size)</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid. Values of 0 mean &quot;use current/default&quot;.</li><li><strong>Postconditions</strong>: The configuration values are updated.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>ctx</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-static-sendfile" tabindex="-1">uvhttp_static_sendfile <a class="header-anchor" href="#uvhttp-static-sendfile" aria-label="Permalink to &quot;uvhttp_static_sendfile&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_result_t uvhttp_static_sendfile(const char* file_path, void* response)</code></li><li><strong>Purpose</strong>: Send a file using zero-copy sendfile (uses default config)</li><li><strong>Preconditions</strong>: <code>file_path</code> must be non-NULL and point to an existing file. <code>response</code> must be a valid <code>uvhttp_response_t*</code>.</li><li><strong>Postconditions</strong>: File is sent with automatic strategy selection based on file size.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: any argument is NULL</li><li><code>UVHTTP_ERROR_NOT_FOUND</code>: file does not exist</li><li><code>UVHTTP_ERROR_OUT_OF_MEMORY</code>: allocation failure</li><li><code>UVHTTP_ERROR_RESPONSE_SEND</code>: sendfile syscall failure</li><li><code>UVHTTP_ERROR_SERVER_INIT</code>: failed to get client fd</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-static-check-conditional-request" tabindex="-1">uvhttp_static_check_conditional_request <a class="header-anchor" href="#uvhttp-static-check-conditional-request" aria-label="Permalink to &quot;uvhttp_static_check_conditional_request&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>int uvhttp_static_check_conditional_request(void* request, const char* etag, time_t last_modified)</code></li><li><strong>Purpose</strong>: Check If-None-Match and If-Modified-Since headers</li><li><strong>Preconditions</strong>: <code>request</code> must be non-NULL.</li><li><strong>Postconditions</strong>: Returns 1 if the client&#39;s cached version is still valid (return 304), 0 otherwise.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h3 id="uvhttp-static-set-response-headers" tabindex="-1">uvhttp_static_set_response_headers <a class="header-anchor" href="#uvhttp-static-set-response-headers" aria-label="Permalink to &quot;uvhttp_static_set_response_headers&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_result_t uvhttp_static_set_response_headers(void* response, const char* file_path, size_t file_size, time_t last_modified, const char* etag)</code></li><li><strong>Purpose</strong>: Set Content-Type, Content-Length, Last-Modified, ETag, and Cache-Control headers</li><li><strong>Preconditions</strong>: <code>response</code> and <code>file_path</code> must be non-NULL.</li><li><strong>Postconditions</strong>: Response headers are set for the file.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>response</code> or <code>file_path</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-static-enable-cache-uvhttp-static-disable-cache" tabindex="-1">uvhttp_static_enable_cache / uvhttp_static_disable_cache <a class="header-anchor" href="#uvhttp-static-enable-cache-uvhttp-static-disable-cache" aria-label="Permalink to &quot;uvhttp_static_enable_cache / uvhttp_static_disable_cache&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_result_t uvhttp_static_enable_cache(uvhttp_static_context_t* ctx, size_t max_memory, int max_entries, int ttl)</code> / <code>void uvhttp_static_disable_cache(uvhttp_static_context_t* ctx)</code></li><li><strong>Purpose</strong>: Enable or disable the LRU cache at runtime</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid.</li><li><strong>Postconditions</strong>: Cache is enabled with the specified parameters or disabled (all entries freed).</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>ctx</code> is NULL</li><li><code>UVHTTP_ERROR_OUT_OF_MEMORY</code>: cache allocation failure</li></ul></li></ul><h3 id="uvhttp-static-set-cache-config" tabindex="-1">uvhttp_static_set_cache_config <a class="header-anchor" href="#uvhttp-static-set-cache-config" aria-label="Permalink to &quot;uvhttp_static_set_cache_config&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_static_set_cache_config(uvhttp_static_context_t* ctx, size_t max_cache_size, int max_entries, int cache_ttl)</code></li><li><strong>Purpose</strong>: Update cache configuration parameters at runtime</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid.</li><li><strong>Postconditions</strong>: Cache parameters are updated. Values of 0 mean &quot;no change&quot;.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>ctx</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h2 id="behavior-rules" tabindex="-1">Behavior Rules <a class="header-anchor" href="#behavior-rules" aria-label="Permalink to &quot;Behavior Rules&quot;">​</a></h2><ol><li><p><strong>Root directory isolation</strong>: All file paths are resolved relative to the configured root directory. Path traversal is prevented via <code>realpath</code> canonicalization and prefix comparison.</p></li><li><p><strong>Send strategy by file size</strong>: Files smaller than 4KB use direct read I/O. Files between 4KB and 10MB use chunked async sendfile. Files larger than 10MB use sendfile zero-copy. On sendfile failure, the system falls back to chunked transfer.</p></li><li><p><strong>LRU cache integration</strong>: The cache stores file content, MIME type, ETag, and last-modified time. Cache lookups use the canonicalized file path as key. Cache expiry is based on TTL (default 3600 seconds).</p></li><li><p><strong>Conditional request handling</strong>: ETag (If-None-Match) is checked first. Last-Modified (If-Modified-Since) is checked second. If either indicates the cached version is valid, a 304 Not Modified response is returned.</p></li><li><p><strong>Directory listing</strong>: When enabled, directory requests generate an auto-index HTML page with entries sorted by type (directories first) then by name. File names are HTML-escaped to prevent XSS.</p></li><li><p><strong>Index file fallback</strong>: Directory requests without an index file fall back to directory listing (if enabled) or return 404.</p></li><li><p><strong>File size limit</strong>: Files exceeding <code>max_file_size</code> return a 413 Payload Too Large response to prevent DoS.</p></li><li><p><strong>Double-free protection</strong>: <code>uvhttp_static_free</code> handles NULL gracefully. Context memory is freed exactly once.</p></li><li><p><strong>sendfile retry</strong>: On EINTR/EAGAIN, sendfile retries up to <code>sendfile_max_retry</code> times (default 2). Timeout is enforced via a timer (default 30 seconds).</p></li><li><p><strong>TCP_CORK optimization</strong>: For large file sends via sendfile, TCP_CORK is enabled to coalesce packets and disabled on completion.</p></li></ol><h2 id="performance-requirements" tabindex="-1">Performance Requirements <a class="header-anchor" href="#performance-requirements" aria-label="Permalink to &quot;Performance Requirements&quot;">​</a></h2><ul><li>MIME type lookup: O(1) via hash table (with linear fallback for collisions)</li><li>Safe path resolution: O(n) where n is path length</li><li>ETag generation: O(1)</li><li>Cache lookup: O(1) amortized via LRU hash table</li><li>sendfile: O(1) per chunk; zero-copy kernel-space transfer</li><li>Memory: ~256 bytes per context instance, plus per-file cache entries</li><li>Cache eviction: batch eviction (default 10 entries) for amortized O(1) insertion</li></ul><h2 id="test-requirements" tabindex="-1">Test Requirements <a class="header-anchor" href="#test-requirements" aria-label="Permalink to &quot;Test Requirements&quot;">​</a></h2><ul><li>Creation and destruction of static context (with and without cache)</li><li>File serving with various file sizes (small, medium, large)</li><li>MIME type detection for all supported extensions</li><li>Unknown extension returns &quot;application/octet-stream&quot;</li><li>Path traversal attack prevention (e.g., <code>../../etc/passwd</code>)</li><li>Conditional request handling (If-None-Match, If-Modified-Since)</li><li>304 Not Modified response correctness</li><li>Directory listing generation and HTML escaping</li><li>Cache prewarm (single file and directory)</li><li>Cache statistics and hit rate calculation</li><li>Cache expiry and cleanup</li><li>sendfile fallback on failure</li><li>sendfile timeout and retry behavior</li><li>File size limit enforcement (413 response)</li><li>NULL parameter handling for all public functions</li><li>Memory cleanup (no leaks on free)</li><li>Feature gate: builds without UVHTTP_FEATURE_STATIC_FILES</li></ul>',46)])])}const p=e(s,[["render",r]]);export{_ as __pageData,p as default};
